 for(const inst of fr.findAll(n=>n.type=='INSTANCE'&&n.name=='Current=Home'||n.type=='INSTANCE'&&n.name.startsWith('Current='))){
  if(inst.mainComponent?.parent?.name!='Header')continue;
  for(const [item,dest] of [['Home','01_Home'],['Blog','03_Blog'],['Contact','05_Contact'],['Recipes',name=='02_Recipe'?null:null]]){if(!dest)continue;const t=inst.findOne(n=>n.name=='Nav/'+item);if(t){await link(t,dest);log.push(name+' '+item)}}}
 if(name!='02_Recipe'){for(const c of fr.findAll(n=>n.type=='INSTANCE'&&n.name=='Recipe Card')){const t=c.findOne(n=>n.name=='Title');if(t&&t.characters=='Healthy Japanese Fried Rice with Asparagus'){await link(c,'02_Recipe');log.push(name+' card')}}}
}
const bl=F['03_Blog'].findOne(n=>n.name=='Article Item: Full Guide to Becoming a Professional Chef');await link(bl,'04_Blog_Post');
return log.join(', ')

